import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Soma — Local-First Workspace Platform","description":"","frontmatter":{},"headers":[],"relativePath":"00-overview.md","filePath":"00-overview.md","lastUpdated":1780254295000}'),r={name:"00-overview.md"};function l(s,e,n,c,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="soma-—-local-first-workspace-platform" tabindex="-1">Soma — Local-First Workspace Platform <a class="header-anchor" href="#soma-—-local-first-workspace-platform" aria-label="Permalink to &quot;Soma — Local-First Workspace Platform&quot;">​</a></h1><p>Soma is a <strong>desktop-first, offline-capable workspace platform</strong> centered on structured note-taking and collaboration.</p><p>It is designed for:</p><ul><li>anyone who wants a structured, local-first note-taking app</li><li>teams and small groups collaborating privately</li><li>people working in offline-sensitive environments</li><li>employees in organizations with restricted connectivity</li></ul><p>It combines:</p><ul><li>a Notion-like note-taking experience</li><li>private workspaces with memberships and approvals</li><li>peer-to-peer data resolution and caching</li><li>capability-based permissions for humans and bots</li><li>optional local AI assistance</li><li>a planned typing-practice surface (Tapia, to be merged in as the <code>/practice</code> route)</li></ul><p>Human roles inside a space stay intentionally simple:</p><ul><li>owners manage access and settings</li><li>editors can create and edit content</li><li>viewers can read without editing</li><li>members are general participants when you do not need a more specific role yet</li><li>bots are non-human peers that must be granted access intentionally</li></ul><p>Bot work should be framed in three categories:</p><ul><li>cache and serve content already allowed for that space</li><li>organize and index content for search or structure</li><li>run approved automation or scripts</li></ul><p>None of these categories are implied just by giving a peer the Bot role.</p><p>Soma is designed to work:</p><ul><li>fully offline on a local network</li><li>partially online (mixed local + remote)</li><li>across the internet when available without requiring a browser or cloud accounts.</li></ul><p>The network model is simple:</p><ul><li>if a peer in the network already has the content, another peer should be able to resolve it from there</li><li>internet infrastructure helps, but it is not supposed to be the only path to useful work</li><li>private workspaces should be able to exist without sharing their content with the outside world</li></ul><hr><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><h3 id="spaces-and-workspaces" tabindex="-1">Spaces and workspaces <a class="header-anchor" href="#spaces-and-workspaces" aria-label="Permalink to &quot;Spaces and workspaces&quot;">​</a></h3><p>A <strong>Space</strong> is the main unit of sharing, permissions, and local collaboration.</p><p>A space contains:</p><ul><li>pages and structured notes</li><li>documents</li><li>attachments (blobs)</li><li>optional AI-assisted workflows</li><li>members (humans and bots)</li></ul><p>A device can be enrolled in <strong>multiple spaces at the same time</strong>.</p><p>Workspaces are intended to support small groups who want to collaborate privately, without exposing content to the public internet by default.</p><hr><h3 id="local-first" tabindex="-1">Local-first <a class="header-anchor" href="#local-first" aria-label="Permalink to &quot;Local-first&quot;">​</a></h3><ul><li>No mandatory server</li><li>LAN-first discovery</li><li>Internet is optional</li><li>Data stays with the space</li></ul><p>The peer-to-peer layer exists to improve reachability and availability, especially in places where the internet is expensive, unstable, filtered, or simply not always there.</p><hr><h3 id="bots" tabindex="-1">Bots <a class="header-anchor" href="#bots" aria-label="Permalink to &quot;Bots&quot;">​</a></h3><p>A <strong>bot</strong> is a special space member:</p><ul><li>can cache and serve resources</li><li>can organize or index workspace content</li><li>can perform approved automation</li><li>can accept or process membership flows when authorized</li><li>may run scripts or background jobs if granted that capability</li></ul><p>Bots can run:</p><ul><li>on a NAS or shared server</li><li>on an office or team machine</li><li>on Soma-operated infrastructure</li><li>on multiple locations for redundancy</li></ul><p>Workspace owners or trusted admins can remove a bot at any time, which revokes its authority for that space.</p><hr><h3 id="identity-security" tabindex="-1">Identity &amp; security <a class="header-anchor" href="#identity-security" aria-label="Permalink to &quot;Identity &amp; security&quot;">​</a></h3><ul><li>No usernames or passwords</li><li>Each device has a cryptographic identity (PeerId)</li><li>Human names are UI-only</li><li>Access is controlled by signed capabilities</li></ul><p>Capabilities are intended to cover permissions for both humans and bots, such as:</p><ul><li>accepting new members</li><li>reading and editing pages</li><li>serving cached content</li><li>running scripts or automation</li></ul><hr><h3 id="architecture-high-level" tabindex="-1">Architecture (high level) <a class="header-anchor" href="#architecture-high-level" aria-label="Permalink to &quot;Architecture (high level)&quot;">​</a></h3><ul><li><strong>Desktop app</strong> (Tauri V2: React/Vite renderer over a Rust <code>src-tauri</code> host) with the daemon + agent runtimes embedded in-process and exposed to the renderer via <code>@soma/sdk</code> over Tauri commands</li><li><strong><code>somad</code> server binary</strong> (with <code>bot</code> / <code>relay</code> / <code>rendezvous</code> / <code>bff</code> / <code>all</code> subcommands)</li><li><strong>Bot peers</strong> (<code>somad bot</code>: cache + onboarding)</li><li><strong>Relay + Rendezvous</strong> (<code>somad relay</code> / <code>somad rendezvous</code>: connectivity only)</li></ul><hr><h2 id="tapia-typing-practice-inside-soma" tabindex="-1">Tapia: typing practice inside Soma <a class="header-anchor" href="#tapia-typing-practice-inside-soma" aria-label="Permalink to &quot;Tapia: typing practice inside Soma&quot;">​</a></h2><p>Tapia is the focused typing-practice surface planned for the Soma desktop app.</p><ul><li>to be accessed at <code>/practice</code> inside Soma — there is no separate app to install or launch. The <code>/practice</code> route is <strong>not yet wired in the Tauri app</strong>; the migration is a tracked follow-up.</li><li>short passages, generated drills, and per-session feedback</li><li>pure-renderer (no daemon dependency); shares the same shell, theming, and shared UI packages as the rest of Soma</li><li>intentionally narrower in scope than Soma&#39;s main workspace surfaces</li></ul><hr><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><ul><li>Offline-first &gt; Cloud-first</li><li>Capabilities &gt; Accounts</li><li>Explicit trust &gt; Implicit trust</li><li>Simple UX &gt; Enterprise complexity</li><li>Structured workspaces &gt; generic file dumping</li></ul>',49)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
